    "section": "history",
    "category": "The Manhattan Project & the Atomic Bomb",
    "summary": "From 1943 the Y-12 plant at Oak Ridge used more than a thousand calutrons, with magnet coils made from about 13,500–14,700 tons of borrowed Treasury silver, to enrich the uranium for Little Boy; the last 67 tons of silver were returned only in 1970.",
    "thumbnail": "assets/images/history/102-y12-calutron-silver/thumbnail.webp",
