    "publishedAt": "2026-10-24T05:55:13Z",
    "section": "theory",
    "category": "Long-Term Core Behavior & Fuel Cycle",
    "summary": "The power peaking factor is the highest local power in the core divided by the core-average power; since safety limits are reached first at that hot spot, bringing the factor closer to 1 lets the whole core produce more power within the same limits.",
