    "summary": "In batch operation a reactor loads fuel as a group and runs continuously for a campaign typically designed around 12, 18 or 24 months, then replaces only part of the core (typically about one-third), with cycle length set by balancing capacity factor against enrichment, burnup and safety limits.",
