    "publishedAt": "2026-10-24T05:40:46Z",
    "section": "theory",
    "category": "Heat Transfer & Thermal Hydraulics",
    "summary": "Critical heat flux is the maximum heat flux at which nucleate boiling can be sustained, a condition-dependent threshold estimated with correlations, and reactors keep the margin to it, tracked as DNBR and MDNBR, under design limits and real-time protection.",
