    "publishedAt": "2026-10-24T05:40:46Z",
    "section": "theory",
    "category": "Heat Transfer & Thermal Hydraulics",
    "summary": "In nucleate boiling, bubbles form and leave while liquid keeps touching the surface, boosting heat transfer; in film boiling, merged bubbles form a vapor film that insulates the surface, which is why reactors use the first and are designed to avoid the second.",
