    "section": "theory",
    "category": "Heat Transfer & Thermal Hydraulics",
    "summary": "Heat from a fuel pellet reaches the coolant by crossing the gas gap and the cladding, and with nearly the same heat flux through each layer, the temperature drop ΔT ≈ q″ × Δx ÷ k is largest where conductivity is low, which is why the thin helium-filled gap can take an unusually large drop.",
